    const payload = typedNative(native, binding);
    if (payload?.kind !== 'change-request' || native.commit_id !== payload.reviewed_head_sha) fail('AUTHORITY_NATIVE_KIND_MISMATCH');
    validateAuthorityRecord(payload, binding);
