  if (record.status) lines.push('', `Status: ${text(record.status)}${record.kind === 'outcome' ? ' (execution claim)' : ''}`);
  if (record.verdict || record.kind === 'change-request') lines.push('', `Verdict: ${text(record.verdict ?? 'REQUEST_CHANGES')}`);
