      // Restore that exact receipt, including warnings, without recollection.
      if (preflight.outcome?.status !== 'IMPLEMENTED_PENDING_FRESH_REVIEW'
        || preflight.outcome.head !== preflight.finalHead) fail('TERMINAL_STATE_INVALID');
