      if (Buffer.byteLength(encoded) > RUNTIME_FALLBACK_BYTES) fail('DIAGNOSTIC_FALLBACK_TOO_LARGE');
      const previous = await lstat(path).catch(error => { if (error.code !== 'ENOENT') throw error; return null; });
