    const decisive = [...records.values()].filter(r => r.kind === 'review' && r.parent.number === pr.number
      && r.author?.id === author.id && ['CHANGES_REQUESTED', 'APPROVED', 'DISMISSED'].includes(r.state)).sort((a, b) => a.id - b.id).at(-1);
